INSERT INTO public.recipes (id, nom, description, saison, mois, mois_numero, semaine, jour, tag, categorie, theme_special, portions, estimated_time, difficulty, image_url, ingredients, instructions, astuce, cuisson_micro_ondes, sans_four, source, source_pdf, source_page, dietary_tags, main_ingredients, equipment, canonical_ingredients_status)
VALUES
  ('city-cafe-gnocchetti-sardi-courgettes-grillees-saumon', 'Gnocchetti sardi aux courgettes grillées et au saumon', 'Malloreddus sardes mêlés à des courgettes dorées, du saumon poêlé et une sauce légère au citron.', 'été', 'août', 8, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'facile', 'https://images.pexels.com/photos/39107658/pexels-photo-39107658.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Gnocchetti sardi","quantity":"180","unit":"g secs","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Saumon","quantity":"260","unit":"g sans peau","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Courgettes","quantity":"200","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"1","unit":"gousse","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Citrons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"2","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Crème","quantity":"60","unit":"ml","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Parmesan","quantity":"20","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"}]'::jsonb, '["Porter une casserole d’eau salée à ébullition et cuire les gnocchetti selon le paquet, généralement 10 à 12 minutes; réserver une louche d’eau de cuisson.","Couper les courgettes en demi-rondelles. Les dorer 6 à 8 minutes dans une grande poêle avec une cuillère d’huile, puis réserver.","Couper le saumon en cubes, saler et poivrer, puis le saisir 2 à 3 minutes par face dans la poêle jusqu’à ce qu’il soit opaque à cœur.","Faire revenir l’ail haché 30 secondes, ajouter la crème, le zeste et le jus de citron, puis détendre avec un peu d’eau de cuisson.","Ajouter les pâtes égouttées et les courgettes. Mélanger doucement, déposer le saumon et servir avec le parmesan."]'::jsonb, 'Les malloreddus sont aussi vendus sous le nom de gnocchetti sardi; à défaut, des petites pâtes torsadées conviennent.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['gnocchetti sardi', 'saumon', 'courgettes']::text[], array['casserole', 'grande poêle', 'zesteur', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-spaghetti-bolognaise', 'Spaghetti bolognaise', 'Spaghetti enrobés d’un ragù maison de bœuf mijoté avec tomate, carotte, céleri et vin rouge.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 75, 'facile', 'https://images.pexels.com/photos/30406652/pexels-photo-30406652.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Spaghetti","quantity":"180","unit":"g secs","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Bœuf","quantity":"250","unit":"g haché","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Oignons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Carottes","quantity":"60","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Céleri","quantity":"40","unit":"g branche","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Tomates","quantity":"250","unit":"g concassées","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Concentré de tomate","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Vin rouge","quantity":"80","unit":"ml","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Parmesan","quantity":"25","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"}]'::jsonb, '["Hacher finement l’oignon, la carotte et le céleri.","Chauffer l’huile dans une casserole et faire suer les légumes 5 minutes. Ajouter le bœuf et le faire dorer en l’émiettant.","Incorporer le concentré de tomate, cuire 1 minute, verser le vin et laisser réduire 2 minutes.","Ajouter les tomates concassées et 100 ml d’eau. Couvrir partiellement et laisser mijoter 50 minutes à feu doux en remuant parfois; saler et poivrer.","Cuire les spaghetti al dente dans une grande casserole d’eau salée, égoutter et mélanger au ragù avec un peu d’eau de cuisson si besoin.","Servir avec le parmesan râpé."]'::jsonb, 'Le ragù peut mijoter jusqu’à 2 heures à feu très doux; ajoute un peu d’eau s’il épaissit trop.', false, true, 'broco-chou', null, null, array['protéines']::text[], array['spaghetti', 'bœuf', 'tomates']::text[], array['casserole', 'grande casserole', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-fusilli-alla-norma', 'Fusilli alla Norma', 'Pâtes courtes à la tomate et à l’aubergine dorée, finies au basilic et à la ricotta salata, dans l’esprit de la spécialité de Catane.', 'été', 'août', 8, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 35, 'facile', 'https://images.pexels.com/photos/29039066/pexels-photo-29039066.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Fusilli","quantity":"180","unit":"g secs","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Aubergines","quantity":"250","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Tomates","quantity":"250","unit":"g concassées","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"1","unit":"gousse","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Basilic","quantity":"8","unit":"feuilles","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Ricotta salata","quantity":"35","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Huile d''olive","quantity":"2","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Couper l’aubergine en dés de 2 cm, saler légèrement et laisser dégorger 10 minutes, puis sécher.","Faire dorer l’aubergine en deux fois dans l’huile, 8 à 10 minutes au total. Réserver sur une assiette.","Dans la même poêle, faire revenir l’ail 30 secondes, ajouter les tomates et laisser réduire 12 minutes à feu doux.","Cuire les fusilli al dente dans une casserole d’eau salée; garder une petite louche d’eau de cuisson.","Mélanger pâtes, sauce et aubergine avec un peu d’eau de cuisson. Ajouter le basilic déchiré et servir avec la ricotta salata râpée."]'::jsonb, 'La ricotta salata est une ricotta salée et affinée; si elle est introuvable, utilise un peu de pecorino, plus puissant.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['fusilli', 'aubergines', 'tomates', 'ricotta salata']::text[], array['casserole', 'grande poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-casarecce-sicilienne-thon-olives', 'Casarecce à la sicilienne, thon, olives et câpres', 'Casarecce enrobées de tomate, thon, olives et câpres, une interprétation de la sauce sicilienne distincte de l’alla Norma à l’aubergine.', 'été', 'août', 8, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'facile', 'https://images.pexels.com/photos/8264654/pexels-photo-8264654.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Casarecce","quantity":"180","unit":"g sèches","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Thon","quantity":"140","unit":"g égoutté","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Tomates","quantity":"220","unit":"g concassées","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Olives","quantity":"35","unit":"g noires dénoyautées","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Câpres","quantity":"15","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Ail","quantity":"1","unit":"gousse","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Persil","quantity":"8","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Porter une casserole d’eau salée à ébullition et cuire les casarecce selon le temps indiqué sur le paquet.","Émincer l’ail et couper les olives en deux. Faire revenir l’ail 30 secondes dans l’huile sans le colorer.","Ajouter les tomates, les olives et les câpres rincées; laisser mijoter 10 à 12 minutes.","Égoutter le thon, l’émietter grossièrement et l’ajouter à la sauce pour le réchauffer 2 minutes.","Égoutter les pâtes en réservant un peu d’eau de cuisson. Les mélanger à la sauce, ajouter le persil haché et servir."]'::jsonb, 'Les casarecce se trouvent en épicerie italienne; des fusilli ou des torsades courtes les remplacent facilement.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['casarecce', 'thon', 'olives', 'câpres']::text[], array['casserole', 'sauteuse', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-gnocchis-potiron-bleu-bresse', 'Gnocchis au potiron et au bleu de Bresse', 'Gnocchis poêlés servis avec du potiron rôti et une sauce crémeuse au bleu de Bresse.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 40, 'facile', 'https://images.pexels.com/photos/29208503/pexels-photo-29208503.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Gnocchis","quantity":"400","unit":"g","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Potiron","quantity":"300","unit":"g épluché","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Bleu de Bresse","quantity":"80","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Crème","quantity":"80","unit":"ml","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Beurre","quantity":"15","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Noix","quantity":"20","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sauge","quantity":"4","unit":"feuilles","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Préchauffer le four à 210 °C. Couper le potiron en dés, les déposer sur une plaque, saler et rôtir 20 à 25 minutes jusqu’à tendreté.","Faire dorer les gnocchis dans une poêle avec le beurre 5 à 7 minutes, en les retournant régulièrement.","Verser la crème dans une petite casserole, ajouter le bleu émietté et chauffer doucement en remuant jusqu’à obtenir une sauce lisse.","Ajouter les dés de potiron aux gnocchis et les faire sauter 1 minute.","Napper de sauce au bleu et terminer avec les noix concassées et la sauge finement ciselée."]'::jsonb, 'Le potimarron peut remplacer le potiron sans être épluché après un bon lavage; le bleu de Bresse se substitue mal, mais un bleu doux convient.', false, false, 'broco-chou', null, null, array['végétarien']::text[], array['gnocchis', 'potiron', 'bleu de Bresse']::text[], array['four', 'plaque de cuisson', 'poêle', 'casserole', 'couteau']::text[], 'verified'),
  ('city-cafe-penne-pesto-maison-tomate-mozzarella', 'Penne au pesto maison, tomates et mozzarella', 'Penne assaisonnées d’un pesto de basilic fraîchement mixé, de tomates juteuses et de mozzarella fondante.', 'été', 'août', 8, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 25, 'facile', 'https://images.pexels.com/photos/4518883/pexels-photo-4518883.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Penne","quantity":"180","unit":"g secs","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Basilic","quantity":"25","unit":"g de feuilles","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Parmesan","quantity":"25","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Pignons de pin","quantity":"15","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Ail","quantity":"0.5","unit":"gousse","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"35","unit":"ml","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Tomates","quantity":"180","unit":"g cerises","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Mozzarella","quantity":"100","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"}]'::jsonb, '["Cuire les penne al dente dans une casserole d’eau salée. Réserver 80 ml d’eau de cuisson puis égoutter.","Mixer le basilic, le parmesan, les pignons, l’ail et l’huile jusqu’à obtenir un pesto; ajouter une cuillère d’eau si nécessaire.","Couper les tomates en deux et déchirer la mozzarella en morceaux.","Mélanger les pâtes encore chaudes avec le pesto et un peu d’eau de cuisson pour lier la sauce.","Ajouter tomates et mozzarella, mélanger une fois et servir sans attendre."]'::jsonb, 'Pour une sauce plus douce, remplace la moitié des pignons par des noix de cajou non salées.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['penne', 'basilic', 'tomates', 'mozzarella']::text[], array['casserole', 'mixeur', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-triangoli-courgettes-puttanesca', 'Triangoli aux courgettes, sauce puttanesca', 'Triangoli frais farcis à la courgette, servis avec une sauce vive aux tomates, olives, câpres, ail et anchois.', 'été', 'août', 8, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 25, 'facile', 'https://images.pexels.com/photos/39061616/pexels-photo-39061616.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Triangoli aux courgettes","quantity":"250","unit":"g frais","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Tomates","quantity":"220","unit":"g concassées","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Olives","quantity":"30","unit":"g noires","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Câpres","quantity":"10","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Anchois","quantity":"2","unit":"filets","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Ail","quantity":"1","unit":"gousse","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Piment","quantity":"1","unit":"pincée","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Persil","quantity":"5","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Hacher l’ail et couper les olives en deux. Faire chauffer l’huile dans une sauteuse à feu doux.","Ajouter l’ail, les anchois et le piment; écraser les anchois à la cuillère pendant 1 minute.","Incorporer les tomates, les olives et les câpres rincées, puis laisser mijoter 10 minutes.","Cuire les triangoli selon les instructions du paquet, souvent 3 à 4 minutes s’ils sont frais; les retirer avec une écumoire.","Mélanger délicatement les pâtes à la sauce, ajouter le persil et servir."]'::jsonb, 'Les triangoli farcis aux courgettes sont vendus frais dans certaines épiceries italiennes; des ravioli courgette-ricotta conviennent également.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['triangoli aux courgettes', 'tomates', 'olives', 'câpres']::text[], array['casserole', 'sauteuse', 'écumoire', 'couteau']::text[], 'verified'),
  ('city-cafe-agnolotti-burrata-basilic-pesto', 'Agnolotti à la burrata, basilic et pesto alla genovese', 'Agnolotti frais au cœur crémeux de burrata, relevés d’un pesto génois et de tomates cerises.', 'été', 'août', 8, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 25, 'facile', 'https://images.pexels.com/photos/31779531/pexels-photo-31779531.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Agnolotti à la burrata","quantity":"250","unit":"g frais","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Basilic","quantity":"25","unit":"g de feuilles","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Parmesan","quantity":"20","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Pignons de pin","quantity":"15","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Ail","quantity":"0.5","unit":"gousse","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"30","unit":"ml","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Tomates","quantity":"120","unit":"g cerises","canonical":true,"category":"Fruits, légumes et légumineuses"}]'::jsonb, '["Mixer le basilic, le parmesan, les pignons, l’ail et l’huile pour obtenir un pesto épais.","Porter une casserole d’eau salée à frémissement et cuire les agnolotti selon le paquet, sans les faire bouillir trop vivement.","Prélever une petite tasse d’eau de cuisson. Égoutter délicatement les pâtes avec une écumoire.","Délayer le pesto avec une à deux cuillères d’eau de cuisson puis napper les agnolotti.","Ajouter les tomates cerises coupées en deux et servir avec un peu de parmesan."]'::jsonb, 'Les agnolotti à la burrata sont parfois vendus surgelés ou frais en épicerie italienne; suivre leur temps de cuisson indiqué et éviter de les manipuler vivement.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['agnolotti à la burrata', 'basilic', 'pesto']::text[], array['casserole', 'mixeur', 'écumoire', 'couteau']::text[], 'verified'),
  ('city-cafe-tagliatelles-vertes-boulettes-veau', 'Tagliatelles vertes et boulettes de veau', 'Tagliatelles aux épinards accompagnées de boulettes de veau moelleuses et d’une sauce tomate courte.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 40, 'facile', 'https://images.pexels.com/photos/14930760/pexels-photo-14930760.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Tagliatelles vertes","quantity":"180","unit":"g fraîches","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Veau","quantity":"240","unit":"g haché","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Œufs","quantity":"0.5","unit":"pièce","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Chapelure","quantity":"20","unit":"g","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Parmesan","quantity":"20","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Tomates","quantity":"200","unit":"g concassées","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Oignons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Persil","quantity":"5","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Mélanger le veau haché avec l’œuf battu, la chapelure, la moitié du parmesan, du sel et du poivre. Former 8 petites boulettes.","Faire dorer les boulettes dans l’huile 5 minutes en les retournant; réserver.","Faire revenir l’oignon finement haché dans la même poêle 3 minutes, ajouter les tomates et 100 ml d’eau.","Remettre les boulettes dans la sauce, couvrir et cuire doucement 15 minutes jusqu’à cuisson complète du veau.","Cuire les tagliatelles selon le paquet, les égoutter et les répartir avec la sauce et les boulettes.","Parsemer de persil et du reste de parmesan."]'::jsonb, 'Des tagliatelles fraîches vertes du commerce sont adaptées; des tagliatelles classiques conviennent si vous n’en trouvez pas.', false, true, 'broco-chou', null, null, array['protéines']::text[], array['tagliatelles vertes', 'veau', 'tomates']::text[], array['casserole', 'poêle avec couvercle', 'saladier', 'couteau']::text[], 'verified'),
  ('city-cafe-ravioli-citron-grana-basilic', 'Ravioli au citron, crème de Grana Padano et basilic', 'Ravioli frais nappés d’une sauce douce au Grana Padano, éclairée par le citron et le basilic frais.', 'printemps', 'avril', 4, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 25, 'facile', 'https://images.pexels.com/photos/30302239/pexels-photo-30302239.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Ravioli","quantity":"250","unit":"g frais","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Crème","quantity":"120","unit":"ml","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Grana Padano","quantity":"45","unit":"g râpé","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Citrons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Basilic","quantity":"8","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Beurre","quantity":"10","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"}]'::jsonb, '["Porter une casserole d’eau salée à frémissement et cuire les ravioli selon le temps du paquet; réserver une petite louche d’eau.","Faire fondre le beurre dans une petite casserole à feu doux, ajouter la crème et le zeste finement râpé du citron.","Incorporer le Grana Padano en fouettant jusqu’à ce qu’il fonde; ajouter une cuillère d’eau de cuisson pour assouplir la sauce.","Égoutter délicatement les ravioli et les enrober de sauce sans les casser.","Ajouter quelques gouttes de jus de citron, le basilic ciselé et servir immédiatement."]'::jsonb, 'Choisir des ravioli frais ricotta-épinards ou ricotta-citron du commerce; la sauce citronnée les accompagne bien sans fabrication de pâte maison.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['ravioli', 'Grana Padano', 'citron', 'basilic']::text[], array['casserole', 'petite casserole', 'fouet', 'zesteur']::text[], 'verified'),
  ('city-cafe-risotto-milanais-truffe-burrata-roquette', 'Risotto milanais à la truffe, burrata et roquette', 'Risotto au safran cuit progressivement au bouillon, terminé au beurre et au Grana Padano, avec burrata, roquette et huile de truffe.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 40, 'intermédiaire', 'https://images.pexels.com/photos/6216844/pexels-photo-6216844.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Riz","quantity":"160","unit":"g spécial risotto","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Oignons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Bouillon","quantity":"650","unit":"ml chaud","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Vin blanc","quantity":"70","unit":"ml","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Safran","quantity":"0.15","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Beurre","quantity":"25","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Grana Padano","quantity":"35","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Burrata","quantity":"1","unit":"petite (125 g)","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Roquette","quantity":"25","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile de truffe","quantity":"1","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Faire chauffer le bouillon dans une petite casserole et y laisser infuser le safran.","Faire fondre 10 g de beurre dans une sauteuse. Ajouter l’oignon finement haché et le cuire 3 minutes sans coloration.","Verser le riz et remuer 1 minute pour l’enrober. Ajouter le vin blanc et laisser évaporer.","Ajouter le bouillon chaud louche par louche en remuant souvent, pendant 18 à 20 minutes, jusqu’à ce que le riz soit crémeux et encore légèrement ferme.","Hors du feu, incorporer le reste du beurre et le Grana Padano. Couvrir 2 minutes.","Répartir le risotto, ajouter la burrata déchirée et la roquette, puis quelques gouttes d’huile de truffe."]'::jsonb, 'L’huile de truffe est puissante : commence par quelques gouttes et ajuste à table. L’Arborio ou le Carnaroli conviennent au risotto.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['riz', 'safran', 'burrata', 'roquette']::text[], array['sauteuse', 'petite casserole', 'louche', 'râpe']::text[], 'verified'),
  ('city-cafe-cannellonis-potimarron-chevre-frais', 'Cannellonis au potimarron et chèvre frais', 'Cannellonis farcis d’une purée de potimarron rôtie et de chèvre frais, gratinés sous une sauce tomate légère.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 60, 'facile', 'https://images.pexels.com/photos/36701467/pexels-photo-36701467.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Cannellonis","quantity":"6","unit":"tubes secs","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Potimarron","quantity":"300","unit":"g épluché et épépiné","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Chèvre","quantity":"100","unit":"g frais","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Ricotta","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Tomates","quantity":"250","unit":"g concassées","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Oignons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Parmesan","quantity":"20","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préchauffer le four à 200 °C. Couper le potimarron en cubes et le rôtir 20 minutes sur une plaque avec un filet d’huile.","Écraser le potimarron rôti avec le chèvre frais et la ricotta. Saler, poivrer et garnir les cannellonis secs à l’aide d’une petite cuillère.","Verser les tomates concassées et l’oignon haché dans le fond d’un petit plat à gratin; ajouter 100 ml d’eau et assaisonner.","Ranger les cannellonis dans la sauce en une seule couche. Couvrir le plat de papier cuisson puis d’aluminium et cuire 25 minutes.","Retirer la couverture, parsemer de parmesan et remettre au four 8 à 10 minutes, jusqu’à ce que les pâtes soient tendres et le dessus doré.","Laisser reposer 5 minutes avant de servir."]'::jsonb, 'Les cannellonis secs ne nécessitent pas de précuisson si la sauce est assez fluide et le plat couvert au début de la cuisson.', false, false, 'broco-chou', null, null, array['végétarien']::text[], array['cannellonis', 'potimarron', 'chèvre frais']::text[], array['four', 'plaque de cuisson', 'plat à gratin', 'cuillère']::text[], 'verified'),
  ('city-cafe-spaghetti-gambas-ail-persil', 'Spaghettis frais aux gambas, ail et persil', 'Spaghettis frais sautés avec des gambas, de l’ail, du persil et un trait de citron.', 'été', 'juillet', 7, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 25, 'facile', 'https://images.pexels.com/photos/30579195/pexels-photo-30579195.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Spaghetti","quantity":"180","unit":"g frais","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Gambas","quantity":"240","unit":"décortiquées","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Ail","quantity":"2","unit":"gousses","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Persil","quantity":"12","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Citrons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"2","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Piment","quantity":"1","unit":"pincée","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Cuire les spaghettis frais selon le paquet, souvent 2 à 4 minutes; réserver une petite tasse d’eau de cuisson.","Émincer l’ail et hacher le persil. Faire chauffer l’huile dans une grande poêle avec le piment.","Ajouter les gambas et les saisir 1 à 2 minutes par face jusqu’à ce qu’elles soient roses et opaques.","Ajouter l’ail et cuire 30 secondes sans le laisser brunir. Verser un peu d’eau de cuisson et le jus de citron.","Ajouter les pâtes égouttées et le persil, mélanger 30 secondes et servir aussitôt."]'::jsonb, 'Si les gambas sont surgelées, les décongeler au réfrigérateur et les sécher avant cuisson pour bien les saisir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['spaghettis frais', 'gambas', 'ail', 'persil']::text[], array['casserole', 'grande poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-crozets-gratines-vacherin-champignons', 'Crozets gratinés au Vacherin et champignons des bois', 'Crozets savoyards mélangés à des champignons poêlés et gratinés avec du Vacherin fondant.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 45, 'facile', 'https://images.pexels.com/photos/14623907/pexels-photo-14623907.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Crozets","quantity":"160","unit":"g secs","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Champignons des bois","quantity":"180","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Vacherin","quantity":"100","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Crème","quantity":"80","unit":"ml","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Échalotes","quantity":"1","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Beurre","quantity":"15","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Noix","quantity":"15","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préchauffer le four en mode gril à 220 °C. Cuire les crozets dans l’eau bouillante salée selon le paquet, puis égoutter.","Nettoyer les champignons avec un linge humide et les couper en morceaux. Hacher l’échalote.","Faire fondre le beurre dans une poêle, cuire l’échalote 2 minutes puis ajouter les champignons et les faire dorer 6 à 8 minutes.","Ajouter la crème, poivrer et mélanger avec les crozets égouttés.","Verser dans un petit plat à gratin, répartir le Vacherin en morceaux et gratiner 5 à 7 minutes jusqu’à ce que le fromage fonde et dore.","Ajouter les noix concassées au moment de servir."]'::jsonb, 'À défaut de Vacherin Mont-d’Or, un reblochon ou un fromage à pâte molle de montagne donnera un gratin fondant.', false, false, 'broco-chou', null, null, array['végétarien']::text[], array['crozets', 'champignons des bois', 'Vacherin']::text[], array['casserole', 'poêle', 'plat à gratin', 'four', 'couteau']::text[], 'verified'),
  ('city-cafe-pastitsio-boeuf-braise', 'Pastitsio au bœuf braisé', 'Gratin grec de macaroni, bœuf longuement mijoté à la tomate et aux épices, recouvert d’une béchamel dorée au fromage.', 'hiver', 'janvier', 1, null, null, 'déjeuner/dîner', 'salé', null, '4 personnes', 225, 'intermédiaire', 'https://images.pexels.com/photos/4661987/pexels-photo-4661987.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Macaroni","quantity":"300","unit":"g","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Bœuf","quantity":"500","unit":"g à braiser en petits dés","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Oignons","quantity":"1","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"2","unit":"gousses","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Tomates","quantity":"400","unit":"g concassées","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Vin rouge","quantity":"120","unit":"ml","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Bouillon","quantity":"250","unit":"ml","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Cannelle","quantity":"0.5","unit":"c. à café","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Beurre","quantity":"40","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Farine","quantity":"40","unit":"g","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Lait","quantity":"500","unit":"ml","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Œufs","quantity":"1","unit":"jaune","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Parmesan","quantity":"50","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Muscade","quantity":"1","unit":"pincée","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Préchauffer le four à 180 °C. Faire dorer les dés de bœuf dans une cocotte avec un peu de beurre ou d’huile, en plusieurs fois.","Ajouter l’oignon haché et l’ail, cuire 3 minutes, puis verser le vin rouge et laisser réduire de moitié.","Ajouter les tomates, le bouillon, la cannelle, du sel et du poivre. Couvrir et laisser braiser à feu doux 2 heures 30, jusqu’à ce que la viande s’effiloche; effilocher grossièrement.","Cuire les macaronis 2 minutes de moins que le temps du paquet, égoutter et répartir dans un plat à gratin. Étaler le bœuf et sa sauce par-dessus.","Pour la béchamel, faire fondre 40 g de beurre dans une casserole, ajouter la farine et fouetter 1 minute. Verser le lait progressivement en fouettant et cuire 5 à 7 minutes jusqu’à épaississement.","Hors du feu, incorporer le jaune d’œuf, la moitié du parmesan et la muscade. Verser sur la viande, parsemer du reste de parmesan.","Enfourner 30 à 35 minutes jusqu’à ce que le dessus soit doré. Laisser reposer 15 minutes avant de découper."]'::jsonb, 'Pour réduire le temps, un bœuf haché mijoté 35 minutes convient, mais la version en dés longuement braisés garde le caractère demandé par le menu.', false, false, 'broco-chou', null, null, array['protéines']::text[], array['macaroni', 'bœuf braisé', 'béchamel']::text[], array['cocotte avec couvercle', 'casserole', 'fouet', 'plat à gratin', 'four', 'couteau']::text[], 'verified')
