-- City Café batch 03: recettes. Generated from city-cafe-recipes-batch-03.json.
BEGIN;

ON CONFLICT (name) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

-- Keep ingredient JSON category labels aligned with the canonical ingredient catalog.
UPDATE public.recipes AS recipe
SET ingredients = (
  SELECT jsonb_agg(jsonb_set(item.ingredient, '{category}', to_jsonb(canonical.category), true) ORDER BY item.ordinality)
  FROM jsonb_array_elements(recipe.ingredients) WITH ORDINALITY AS item(ingredient, ordinality)
  JOIN public.ingredients AS canonical ON canonical.name = item.ingredient->>'name'
)
WHERE recipe.id IN ('city-cafe-gnocchetti-sardi-courgettes-grillees-saumon', 'city-cafe-spaghetti-bolognaise', 'city-cafe-fusilli-alla-norma', 'city-cafe-casarecce-sicilienne-thon-olives', 'city-cafe-gnocchis-potiron-bleu-bresse', 'city-cafe-penne-pesto-maison-tomate-mozzarella', 'city-cafe-triangoli-courgettes-puttanesca', 'city-cafe-agnolotti-burrata-basilic-pesto', 'city-cafe-tagliatelles-vertes-boulettes-veau', 'city-cafe-ravioli-citron-grana-basilic', 'city-cafe-risotto-milanais-truffe-burrata-roquette', 'city-cafe-cannellonis-potimarron-chevre-frais', 'city-cafe-spaghetti-gambas-ail-persil', 'city-cafe-crozets-gratines-vacherin-champignons', 'city-cafe-pastitsio-boeuf-braise');

COMMIT;
